\loigiai{
$\dfrac{10}{9} = \dfrac{50}{45} $ ; $\dfrac{-7}{5} = \dfrac{-63}{45}$\\
Vì ${50}>{-63}$ nên $\dfrac{50}{45} > \dfrac{-63}{45}$ hay  $\dfrac{10}{9}> \dfrac{-7}{5}$
}\end{ex}

